// The folders in the projects folder, or nothing when that folder exists but
// cannot be listed (its permissions, a storage fault): callers say so rather
// than treat it as holding no projects. No projects folder yet is a new
// installation with none.
std::optional<std::vector<std::filesystem::path>> project_folders(const std::filesystem::path& root)
{
    std::vector<std::filesystem::path> folders;
    std::error_code error;
    // exists() clears the error for a path that is not there; is_directory()
    // reports it as an error.
    if (!std::filesystem::exists(root, error) && !error)
        return folders;
    std::filesystem::directory_iterator it(root, error);
    for (const std::filesystem::directory_iterator end; !error && it != end; it.increment(error))
        folders.push_back(it->path());
    if (error) {
        BOOST_LOG_TRIVIAL(error) << "Local projects could not be listed: " << root.string() << ": " << error.message();
        return std::nullopt;
    }
    return folders;
}

// A project has a card once it has held a model, whatever it holds now: a
// person who deleted every object can still go back to an earlier version.
bool authored_head(const std::filesystem::path& project)
{
    std::ifstream head(project / "HEAD", std::ios::binary);
    std::string content((std::istreambuf_iterator<char>(head)), std::istreambuf_iterator<char>());
    if (content.empty()) return false;
    const auto versions = nlohmann::json::parse(content).at("versions").get<std::vector<std::string>>();
    return std::any_of(versions.rbegin(), versions.rend(), [&project](const std::string& id) {
        std::ifstream manifest(project / "versions" / id / "manifest.json", std::ios::binary);
        return manifest && !nlohmann::json::parse(manifest).at("objects").empty();
    });
}

// The MD5 of a file's content; empty when it cannot be read.
std::string file_digest(const std::filesystem::path& path)
{
    try {
        std::string name = path.u8string(), digest;
        return std::filesystem::is_regular_file(path) && bbl_calc_md5(name, digest) ? digest : std::string();
    } catch (const std::exception&) {
        return {};
    }
}

